import json
from itertools import permutations

def solve_puzzle():
    houses = [0, 1, 2, 3]  # indices represent houses 1..4

    Names = ['Arnold', 'Peter', 'Eric', 'Alice']
    HouseStyles = ['craftsman', 'colonial', 'victorian', 'ranch']
    HairColors = ['red', 'blonde', 'black', 'brown']
    Children = ['Bella', 'Fred', 'Meredith', 'Samantha']
    BookGenres = ['mystery', 'fantasy', 'romance', 'science fiction']

    solutions = []

    # Generate permutations for names with constraint: House 2 is Eric (index 1)
    for names in permutations(Names):
        if names[1] != 'Eric':
            continue

        pos_arnold = names.index('Arnold')
        pos_peter = names.index('Peter')
        pos_alice = names.index('Alice')

        # Hair constraints:
        # - House 4 has brown hair (index 3)
        # - House 2 has black hair (index 1)
        # - Arnold has red hair
        for hair in permutations(HairColors):
            if hair[1] != 'black':
                continue
            if hair[3] != 'brown':
                continue
            if hair[pos_arnold] != 'red':
                continue
            # The person with black hair is Eric
            if names[hair.index('black')] != 'Eric':
                continue

            # HouseStyle constraints:
            # - House 3 is craftsman (index 2)
            # - Alice is in colonial-style house
            # - Ranch is to the right of red-haired person
            for styles in permutations(HouseStyles):
                if styles[2] != 'craftsman':
                    continue
                if styles[pos_alice] != 'colonial':
                    continue
                # Ranch to the right of red hair
                if styles.index('ranch') <= hair.index('red'):
                    continue

                # Children constraints:
                # - House 4 child is Samantha (index 3)
                # - Peter's child is Bella
                # - Arnold's child is Meredith
                for kids in permutations(Children):
                    if kids[3] != 'Samantha':
                        continue
                    if kids[pos_peter] != 'Bella':
                        continue
                    if kids[pos_arnold] != 'Meredith':
                        continue

                    # BookGenre constraints:
                    # - Alice loves romance
                    # - Peter loves fantasy
                    # - Arnold loves science fiction
                    for books in permutations(BookGenres):
                        if books[pos_alice] != 'romance':
                            continue
                        if books[pos_peter] != 'fantasy':
                            continue
                        if books[pos_arnold] != 'science fiction':
                            continue

                        solutions.append((names, styles, hair, kids, books))

    # Expect a unique solution
    if not solutions:
        raise RuntimeError("No solution found.")
    # Use the first (unique) solution
    names, styles, hair, kids, books = solutions[0]

    header = ["House", "Name", "HouseStyle", "HairColor", "Children", "BookGenre"]
    rows = []
    for i in range(4):
        rows.append([
            str(i + 1),
            names[i],
            styles[i],
            hair[i],
            kids[i],
            books[i]
        ])

    output = {
        "solution": {
            "header": header,
            "rows": rows
        }
    }
    print(json.dumps(output, ensure_ascii=False, indent=2))

if __name__ == "__main__":
    solve_puzzle()
